// decentralizedMigrationFailed reports whether the VMI's migration has been marked as
// both failed and completed.
func decentralizedMigrationFailed(vmi *virtv1.VirtualMachineInstance) bool {
	return vmi.Status.MigrationState != nil &&
		vmi.Status.MigrationState.Failed &&
		vmi.Status.MigrationState.Completed
}

// podInTerminalState reports whether the pod exists and has reached a terminal
// (Succeeded or Failed) phase.
func podInTerminalState(pod *k8sv1.Pod, vmiPodExists bool) bool {
	return vmiPodExists && pod != nil &&
		(pod.Status.Phase == k8sv1.PodSucceeded || pod.Status.Phase == k8sv1.PodFailed)
}

// migrationTargetShouldWaitForSync reports whether a VMI that is marked as a migration
// target should be (or remain) in the WaitingForSync phase. This is the case when the
// migration has already failed, or when its pod is gone or in a terminal state.
func migrationTargetShouldWaitForSync(vmi *virtv1.VirtualMachineInstance, pod *k8sv1.Pod, vmiPodExists bool) bool {
	if !vmi.IsMigrationTarget() {
		return false
	}
	if decentralizedMigrationFailed(vmi) {
		return true
	}
	return !vmiPodExists || podInTerminalState(pod, vmiPodExists)
}

// markMigrationFailed marks the VMI's migration as failed. Any existing StartTimestamp is
// preserved, the EndTimestamp is set to the current time, and both Completed and Failed
// are set to true.
func markMigrationFailed(vmi *virtv1.VirtualMachineInstance) {
	if vmi.Status.MigrationState == nil {
		return
	}
	vmi.Status.MigrationState.EndTimestamp = pointer.P(metav1.Now())
	vmi.Status.MigrationState.Completed = true
	vmi.Status.MigrationState.Failed = true
